	Maester: { name: 'Maester', slug: 'maester' },
	CIS: { name: 'CIS', slug: 'cis' },
	CISA: { name: 'CISA SCuBA', slug: 'cisa' },
	ASD: { name: 'ASD Essential Eight', slug: 'asd' },
