  AppOnly?: { Supported: boolean; Methods: Record<'Certificate' | 'ClientSecret' | 'ManagedIdentity' | 'WorkloadIdentity', boolean>; Text?: string | null; OtherRoles: string[]; Command?: string | null; More?: string | null } | null;
  Links: { Text: string; Url: string }[]; Support?: { Tests?: string | null; Pack?: string | null } | null;
}
export interface ConnectorSetting { Name: string; Type?: string; Secret: boolean; Environment: string }
export interface Connector { Service: string; DisplayName: string; OptIn: boolean; Platform?: string | null; Settings: ConnectorSetting[] }

export interface IndexRow {
  Id: string; Name: string; Description: string; Source: string; Owner: string; Repo: string; Folder?: string | null;
  Path: string; Version: string; Commit: string; Code: string; Risk: Risk; Badges: string[]; Tests: number;
  Services: string[]; Connectors: string[]; Stars: number; OpenIssues?: number | null; IssuesUrl?: string | null; PublishedAt?: string | null; License?: string | null;
  OpenSource?: boolean; Pricing?: Pricing; Banner?: string | null;
  Kind?: PackKind; Products: string[]; Pillars: string[]; AppOnly?: boolean | null; Connection?: 'Maester' | 'Connector';
}

export type Pricing = 'Free' | 'Paid';
export interface FeaturedPack { row: IndexRow; Blurb: string }

export interface Listing {
  Source: string; Owner: string; Repo: string; Folder?: string | null; RepoId: number; OwnerId: number; OwnerType: string;
  Stars: number; OpenIssues?: number | null; IssuesUrl?: string | null; License?: string | null; OpenSource?: boolean; Pricing?: Pricing; Banner?: string | null; Release: boolean; Immutable: boolean; Ref: string; Commit: string; PublishedAt?: string | null;
  Id: string; Name: string; Description: string; Version: string; Publisher: string; Code: string; RequiresMaester?: string | null;
  Uses?: Record<string, unknown> | null; Connectors: Connector[]; Tests: PackTest[]; Readme?: string | null;
  Risk: Risk; Findings: Finding[]; Binaries: { Path: string; Size: number; Sha256: string; Kind: string; Signer?: string | null }[];
  Warnings: string[]; Digest: string; Official: boolean; Badges: string[]; Reasons: Reason[]; Notices: Reason[];
  Blocked?: { Advisory: string; Reason?: string } | null; Listed: boolean; ScannedAt: string;
  Kind?: PackKind; Products: string[]; Pillars: { Name: string; Count: number }[]; Guide?: Guide | null;
  Screenshots: { Path: string; Caption?: string | null }[]; AppOnly?: boolean | null; Connection?: 'Maester' | 'Connector';
}

export interface CodeClaim { Code: string; Owner: string; OwnerId: number; Source: string; RegisteredAt: string }
export interface ServiceClaim { Service: string; Owner: string; OwnerId: number; Pack: string }
export interface StatusFile { Source: string; CheckedAt: string; Versions: { Source: string; Folder?: string | null; Version?: string | null; Commit?: string | null; Ref?: string | null; Listed: boolean; Reasons: Reason[]; Notices: Reason[]; CheckedAt: string }[] }

function readJson<T>(relative: string, fallback: T): T {
  const file = path.join(dataDir, relative);
  if (!fs.existsSync(file)) return fallback;
  // The indexer writes UTF-8 without a BOM; strip one anyway.
  return JSON.parse(fs.readFileSync(file, 'utf8').replace(/^﻿/, '')) as T;
}

const asArray = <T>(value: T | T[] | null | undefined): T[] => (value == null ? [] : Array.isArray(value) ? value : [value]);

export function getIndex(): { GeneratedAt?: string; Packs: IndexRow[] } {
  const index = readJson<{ GeneratedAt?: string; Packs: IndexRow[] }>('index.json', { Packs: [] });
  index.Packs = asArray(index.Packs).map((p) => ({ ...p, Badges: asArray(p.Badges), Services: asArray(p.Services), Connectors: asArray(p.Connectors), Products: asArray(p.Products), Pillars: asArray(p.Pillars) }));
  return index;
}

export function getListing(row: IndexRow): Listing {
  const l = readJson<Listing>(row.Path, null as unknown as Listing);
  return {
    ...l,
    Connectors: asArray(l.Connectors).map((c) => ({ ...c, Settings: asArray(c.Settings) })),
    Tests: asArray(l.Tests).map((t) => ({ ...t, Service: asArray(t.Service), Product: asArray(t.Product), RelatedProduct: asArray(t.RelatedProduct), Pillar: asArray(t.Pillar) })),
    Products: asArray(l.Products),
    Pillars: asArray(l.Pillars),
    Screenshots: asArray(l.Screenshots),
    Guide: l.Guide ? normaliseGuide(l.Guide) : null,
    Findings: asArray(l.Findings),
    Binaries: asArray(l.Binaries),
    Warnings: asArray(l.Warnings),
    Badges: asArray(l.Badges),
    Reasons: asArray(l.Reasons),
    Notices: asArray(l.Notices),
  };
}

function normaliseGuide(g: Guide): Guide {
  const section = (x: GuideSection | null | undefined) => (x ? { ...x, Steps: asArray(x.Steps), Notes: asArray(x.Notes) } : null);
  return {
    ...g,
    Prerequisites: asArray(g.Prerequisites),
    Connect: section(g.Connect),
    Run: g.Run ? { ...g.Run, Commands: asArray(g.Run.Commands), Options: asArray(g.Run.Options), Notes: asArray(g.Run.Notes) } : null,
    AppOnly: g.AppOnly ? { ...g.AppOnly, OtherRoles: asArray(g.AppOnly.OtherRoles) } : null,
    Links: asArray(g.Links),
  };
}

/**
 * The Microsoft products a test can be about, by the keys of Maester's taxonomy, in the order the report shows them.
 * Each has an icon in public/icons/products (see its NOTICE.md).
 */
export const products: Record<string, string> = {
  entra: 'Entra ID', exchange: 'Exchange Online', defender: 'Defender', intune: 'Intune', purview: 'Purview',
  sharepoint: 'SharePoint', teams: 'Teams', 'microsoft-365': 'Microsoft 365', azure: 'Azure', 'azure-devops': 'Azure DevOps',
  github: 'GitHub', ad: 'Active Directory', 'copilot-studio': 'Copilot Studio',
};

export function productName(key: string): string {
  return products[key] ?? key;
}

export function productIcon(key: string): string | null {
  return products[key] ? `/icons/products/${key}.svg` : null;
}

export const kindText: Record<PackKind, string> = {
  Script: 'PowerShell files only.',
  Module: 'PowerShell files, plus PowerShell modules from the PowerShell Gallery.',
  Binary: 'Carries compiled files, or runs something other than PowerShell.',
};

const compact = new Intl.NumberFormat('en', { notation: 'compact', maximumFractionDigits: 1 });
/** 999, then 1k, 1.2k, 12k, 1.2m. */
export function compactNumber(n: number): string {
  return compact.format(n).toLowerCase();
}

export function kindLabel(kind: PackKind | undefined): string {
  return `${kind ?? 'Script'} pack`;
}

interface ModuleUse { Name: string; Version?: string; MinimumVersion?: string; Install?: string; Process?: string }

