/**
 * The URL path of a pack's page: /p/{code}, such as /p/cnt or /p/cnt.gws. A listed pack's code is registered to it
 * for good (the pack registry), so the URL never changes when the repository is renamed, moved or transferred, and
 * links to it keep working.
 */
/** The pack repository's issues on GitHub, where its own bugs are reported. */
/** Where to report a problem with the pack: the issues page its Guide names, which the index works out, or its repository's. */
export function issuesUrl(p: { Owner: string; Repo: string; IssuesUrl?: string | null }): string {
  return p.IssuesUrl ?? `https://github.com/${p.Owner}/${p.Repo}/issues`;
}

export function packUrl(p: { Code: string }): string {
  return `/p/${p.Code.toLowerCase()}`;
}

/** A publisher's page, listing their packs: /publishers/{owner}. */
export function publisherUrl(owner: string): string {
  return `/publishers/${owner.toLowerCase()}`;
---
// Every page under a pack: /p/{code} (see packUrl) with the tabs overview, tests, connector and
// security, and one page per test (section 8.2).
import Base from '../../layouts/Base.astro';
import RiskPill from '../../components/RiskPill.astro';
import Badges from '../../components/Badges.astro';
import CodeBox from '../../components/CodeBox.astro';
import Select from '../../components/Select.astro';
import ProductIcons from '../../components/ProductIcons.astro';
import { getIndex, getListing, packUrl, publisherUrl, installCommand, isBuiltIn, renderUntrustedMarkdown, riskText, licenceText, shortCommit, formatDate, productName, kindLabel, kindText, packModules, userModuleCommands, graphScopes, compactNumber, issuesUrl, type Listing } from '../../lib/packs';

export function getStaticPaths() {
  const paths = [];
  for (const row of getIndex().Packs) {
    const listing = getListing(row);
    const base = packUrl(row).replace(/^\/p\//, '');
    const props = { listing };
    paths.push({ params: { slug: base }, props: { ...props, tab: 'overview' } });
    for (const tab of ['tests', 'connector', 'security']) paths.push({ params: { slug: `${base}/${tab}` }, props: { ...props, tab } });
    for (const test of listing.Tests.filter((t) => !t.Catalog)) {
      paths.push({ params: { slug: `${base}/tests/${test.Id.toLowerCase()}` }, props: { ...props, tab: 'test', testId: test.Id } });
    }
  }
  return paths;
}

interface Props { listing: Listing; tab: string; testId?: string }
const { listing: l, tab, testId } = Astro.props;
const base = packUrl(l);
const blocked = Boolean(l.Blocked);
