// catalog.json: every listed pack with its tests, for sites that list Maester's checks in one place (maester.dev's
// test catalog reads it at build time). index.json has one row per pack; this adds each pack's tests, with only what
// a listing of them needs. Url is the test's page here, or the pack's tests tab for a test that has none.
import type { APIRoute } from 'astro';
import { getIndex, getListing, packUrl } from '../lib/packs';

export const GET: APIRoute = () => {
  const index = getIndex();
  const packs = index.Packs.map((row) => {
    const listing = getListing(row);
    const base = packUrl(row);
    return {
      Id: row.Id,
      Code: row.Code,
      Name: row.Name,
      Description: row.Description,
      Owner: row.Owner,
      Source: row.Source,
      Version: row.Version,
      Badges: row.Badges,
      Risk: row.Risk,
      Products: row.Products,
      PublishedAt: row.PublishedAt ?? null,
      Url: `https://packs.maester.cloud${base}`,
      Tests: listing.Tests.map((t) => ({
        Id: t.Id,
        Title: t.Title,
        Severity: t.Severity ?? null,
        Product: t.Product,
        Pillar: t.Pillar,
        Category: t.Category ?? null,
        Url: `https://packs.maester.cloud${base}/tests${t.Catalog ? '' : `/${t.Id.toLowerCase()}`}`,
      })),
    };
  });
  const body = JSON.stringify({ Version: 1, GeneratedAt: index.GeneratedAt ?? null, Packs: packs });
  return new Response(body, { headers: { 'Content-Type': 'application/json; charset=utf-8' } });
};
EOF
