$module = Get-Module Maester

# The test each shim returns: a shim is a test whose body is one return of another built-in test's function, a
# benchmark test for a requirement another suite already checks. The rule is the one
# powershell/tests/general/TestShims.Tests.ps1 applies. The site counts each test, and can group a shim with its test.
$idByFunction = @{}
foreach ($t in $tests) { if ($t.FunctionName) { $idByFunction[$t.FunctionName] = $t.Id } }
$shimOf = @{}
foreach ($t in $tests) {
    $ast = [System.Management.Automation.Language.Parser]::ParseFile($t.File, [ref]$null, [ref]$null)
