	.mt-growth__end {
		fill: var(--g-community);
		stroke: var(--sl-color-bg, #fff);
		stroke-width: 2;
	}
	.mt-growth__endlabel {
		fill: var(--sl-color-white);
		font-size: 14px;
		font-weight: 600;
		font-variant-numeric: tabular-nums;
	}
'''
